-- Ignored source20 synthetic-only restricted records; root promotes after review.
begin;
create table app.restricted_record_policies(school_id uuid not null,id uuid not null default gen_random_uuid(),version integer not null check(version>0),enabled boolean not null,purpose text not null check(purpose='BASIC_INCIDENT_NOTE'),source_basis text not null check(source_basis='SCHOOL_AUTHORED'),retention_status text not null check(retention_status='SYNTHETIC_ONLY'),retention_note text not null check(length(btrim(retention_note))between 1 and 1000),owner_id uuid not null,reason text not null check(length(btrim(reason))between 1 and 1000),approved_by uuid not null,approved_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,version),foreign key(school_id,owner_id)references app.memberships(school_id,actor_id),foreign key(school_id,approved_by)references app.memberships(school_id,actor_id));
create table app.restricted_records(school_id uuid not null,policy_id uuid not null,id uuid not null default gen_random_uuid(),course_id uuid not null,learner_id uuid not null,author_id uuid not null,occurred_at timestamptz not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,policy_id)references app.restricted_record_policies(school_id,id),foreign key(school_id,course_id)references app.courses(school_id,id),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id),foreign key(school_id,author_id)references app.memberships(school_id,actor_id));
create table app.restricted_record_revisions(school_id uuid not null,policy_id uuid not null,id uuid not null default gen_random_uuid(),record_id uuid not null,revision integer not null check(revision>0),title text not null check(length(btrim(title))between 1 and 200),note text not null check(length(btrim(note))between 1 and 4000),state text not null check(state in('AWAITING_REVIEW','APPROVED_FOLLOW_UP','IN_PROGRESS','COMPLETED')),follow_up_owner_id uuid,follow_up_instructions text,follow_up_note text,reason text not null check(length(btrim(reason))between 1 and 1000),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,record_id,revision),foreign key(school_id,policy_id)references app.restricted_record_policies(school_id,id),foreign key(school_id,record_id)references app.restricted_records(school_id,id),foreign key(school_id,follow_up_owner_id)references app.memberships(school_id,actor_id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id),check((state='AWAITING_REVIEW'and follow_up_owner_id is null and follow_up_instructions is null and follow_up_note is null)or(state<>'AWAITING_REVIEW'and follow_up_owner_id is not null and follow_up_instructions is not null and length(btrim(follow_up_instructions))between 1 and 4000)),check(follow_up_note is null or length(btrim(follow_up_note))between 1 and 4000));
create function internal.restricted_synthetic_school(target_school uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce(exists(select 1 from app.schools s where s.id=target_school and s.status='active')and exists(select 1 from app.people p where p.school_id=target_school)and not exists(select 1 from app.people p where p.school_id=target_school and p.synthetic is distinct from true),false)$$;
create function internal.restricted_policy_enabled(target_school uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".can_access_school(target_school)and"authorization".has_entitlement(target_school,'restricted.records')and internal.restricted_synthetic_school(target_school)and(select p.enabled from app.restricted_record_policies p where p.school_id=target_school order by p.version desc limit 1),false)$$;
create function internal.restricted_policy_owner(target_school uuid)returns uuid language sql stable security definer set search_path=''as $$select owner_id from app.restricted_record_policies where school_id=target_school order by version desc limit 1$$;
create function internal.restricted_course_teacher(target_school uuid,target_course uuid,target_teacher uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce(exists(select 1 from app.courses c join app.teacher_assignments t on t.school_id=c.school_id and t.class_id=c.class_id and t.subject_id=c.subject_id join app.memberships m on m.school_id=t.school_id and m.actor_id=t.teacher_actor_id where c.school_id=target_school and c.id=target_course and t.teacher_actor_id=target_teacher and t.status='active'and t.effective_from<=now()and(t.effective_to is null or t.effective_to>now())and m.role='teacher'and m.status='active'and m.effective_from<=now()and(m.effective_to is null or m.effective_to>now())),false)$$;
create function internal.restricted_record_allowed(target_record uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce(exists(select 1 from app.restricted_records record left join lateral(select r.follow_up_owner_id from app.restricted_record_revisions r where r.school_id=record.school_id and r.record_id=record.id order by r.revision desc limit 1)revision on true where record.school_id="authorization".school_id()and record.id=target_record and internal.restricted_policy_enabled(record.school_id)and"authorization".current_learner_course(record.school_id,record.course_id,record.learner_id)and(case when"authorization".current_role(record.school_id)='admin'then internal.restricted_policy_owner(record.school_id)="authorization".actor_id()when"authorization".current_role(record.school_id)='teacher'then(record.author_id="authorization".actor_id()or revision.follow_up_owner_id="authorization".actor_id())and internal.restricted_course_teacher(record.school_id,record.course_id,"authorization".actor_id())and"authorization".can_view_person(record.school_id,record.learner_id)else false end)),false)$$;
create function internal.read_restricted_policy()returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();policy app.restricted_record_policies;begin
 if not"authorization".can_access_school(school)or not"authorization".has_entitlement(school,'restricted.records')or"authorization".current_role(school)is null or"authorization".current_role(school)not in('admin','teacher')or not internal.restricted_synthetic_school(school)then raise exception 'Synthetic restricted purpose denied'using errcode='42501';end if;

 select p.*into policy from app.restricted_record_policies p where p.school_id=school order by p.version desc limit 1;return jsonb_build_object('id',coalesce(policy.id,school),'version',coalesce(policy.version,0),'enabled',coalesce(policy.enabled,false),'purpose','BASIC_INCIDENT_NOTE','retentionStatus','SYNTHETIC_ONLY','ownerId',policy.owner_id,'retentionNote',policy.retention_note);
end$$;
create function internal.restricted_record_projection(target uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();answer jsonb;begin
 if not internal.restricted_record_allowed(target)then raise exception 'Current restricted record denied'using errcode='42501';end if;
 select jsonb_build_object('id',record.id,'courseId',record.course_id,'learnerId',record.learner_id,'title',revision.title,'note',revision.note,'occurredAt',record.occurred_at,'revision',revision.revision,'authorId',record.author_id,'authorName',author.display_name,'learnerName',learner.display_name,'courseTitle',course.title,'className',class.name,'state',revision.state,'followUpOwnerId',revision.follow_up_owner_id,'followUpOwnerName',owner.display_name,'followUpInstructions',revision.follow_up_instructions,'followUpNote',revision.follow_up_note,'retentionStatus','SYNTHETIC_ONLY')into answer from app.restricted_records record join lateral(select r.*from app.restricted_record_revisions r where r.school_id=record.school_id and r.record_id=record.id order by r.revision desc limit 1)revision on true join app.people author on author.school_id=record.school_id and author.actor_id=record.author_id join app.people learner on learner.school_id=record.school_id and learner.actor_id=record.learner_id join app.courses course on course.school_id=record.school_id and course.id=record.course_id join app.classes class on class.school_id=course.school_id and class.id=course.class_id left join app.people owner on owner.school_id=record.school_id and owner.actor_id=revision.follow_up_owner_id where record.school_id=school and record.id=target;return answer;
end$$;
create function internal.read_restricted_records(page_limit integer,page_cursor uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();items jsonb;begin
 if "authorization".current_role(school)is null or "authorization".current_role(school)not in('admin','teacher')or not internal.restricted_policy_enabled(school)or page_limit is null or page_limit not between 1 and 25 then raise exception 'Restricted purpose disabled or unbounded'using errcode='42501';end if;
 select coalesce(jsonb_agg(internal.restricted_record_projection(r.id)order by r.id),'[]'::jsonb)into items from(select r.id from app.restricted_records r where r.school_id=school and(page_cursor is null or r.id>page_cursor)and internal.restricted_record_allowed(r.id)order by r.id limit page_limit+1)r;
 if octet_length(items::text)>250000 then raise exception 'Restricted review page exceeds current bound'using errcode='22023';end if;return jsonb_build_object('items',case when jsonb_array_length(items)>page_limit then items-page_limit else items end,'nextCursor',case when jsonb_array_length(items)>page_limit then items->(page_limit-1)->>'id'else null end);
end$$;
create function internal.lock_restricted_relation(target_course uuid,target_learner uuid,target_teacher uuid)returns void language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();begin
 perform 1 from app.memberships m where m.school_id=school and m.actor_id in(target_learner,target_teacher,"authorization".actor_id())order by m.actor_id for share;
 perform 1 from app.enrollments e join app.courses c on c.school_id=e.school_id and c.class_id=e.class_id where c.school_id=school and c.id=target_course and e.student_actor_id=target_learner for share of e;
 perform 1 from app.teacher_assignments t join app.courses c on c.school_id=t.school_id and c.class_id=t.class_id and c.subject_id=t.subject_id where c.school_id=school and c.id=target_course and t.teacher_actor_id=target_teacher order by t.teacher_actor_id,t.subject_id for share of t;
 if not"authorization".current_learner_course(school,target_course,target_learner)then raise exception 'Current restricted learner relation required'using errcode='42501';end if;
end$$;
create function internal.restricted_record_command(command_name text,target uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();role_name text:="authorization".current_role("authorization".school_id());policy app.restricted_record_policies;record app.restricted_records;revision app.restricted_record_revisions;course app.courses;latest integer;rid uuid;record_id uuid;reservation jsonb;receipt jsonb;event_version integer;begin
 perform internal.require_context();if command_name is null or command_name not in('policy','create','correct','approve','followup')then raise exception 'Restricted command invalid'using errcode='22023';end if;if not"authorization".has_entitlement(school,'restricted.records')or not internal.restricted_synthetic_school(school)or role_name is null or role_name not in('admin','teacher')then raise exception 'Synthetic restricted purpose required'using errcode='42501';end if;
 if command_name='policy'then perform pg_advisory_xact_lock(hashtextextended(school::text||':restricted-record-policy',0));else perform pg_advisory_xact_lock_shared(hashtextextended(school::text||':restricted-record-policy',0));end if;
 if payload is null or jsonb_typeof(payload)<>'object'or octet_length(payload::text)>20000 then raise exception 'Restricted source fields invalid'using errcode='22023';end if;
 if command_name='policy'then
  if role_name<>'admin'or payload-array['enabled','expectedVersion','purpose','sourceBasis','retentionStatus','retentionNote','ownerId','reason','confirmApproval']<>'{}'::jsonb or payload->'confirmApproval'is distinct from'true'::jsonb or jsonb_typeof(payload->'enabled')is distinct from'boolean'or payload->>'purpose'is distinct from'BASIC_INCIDENT_NOTE'or payload->>'sourceBasis'is distinct from'SCHOOL_AUTHORED'or payload->>'retentionStatus'is distinct from'SYNTHETIC_ONLY'or jsonb_typeof(payload->'expectedVersion')is distinct from'number'or(payload->>'expectedVersion')!~'^[0-9]+$'or jsonb_typeof(payload->'retentionNote')is distinct from'string'or length(btrim(payload->>'retentionNote'))not between 1 and 1000 or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'Explicit synthetic policy approval required'using errcode='22023';end if;
  if(payload->>'ownerId')::uuid is distinct from actor then raise exception 'Current administrator must own restricted policy'using errcode='42501';end if;
 else
  if not internal.restricted_policy_enabled(school)then raise exception 'Restricted policy disabled'using errcode='42501';end if;
  if command_name='create'then select c.*into course from app.courses c where c.school_id=school and c.id=(payload->>'courseId')::uuid for update;if not found or not"authorization".current_learner_course(school,course.id,(payload->>'learnerId')::uuid)or not(role_name='admin'and internal.restricted_policy_owner(school)=actor or role_name='teacher'and internal.restricted_course_teacher(school,course.id,actor))then raise exception 'Exact current restricted learner course required'using errcode='42501';end if;
  else select r.*into record from app.restricted_records r where r.school_id=school and r.id=target for update;if not found or not internal.restricted_record_allowed(record.id)then raise exception 'Current restricted object scope denied'using errcode='42501';end if;select r.*into revision from app.restricted_record_revisions r where r.school_id=school and r.record_id=record.id order by r.revision desc limit 1;
   if command_name='approve'and(role_name<>'admin'or internal.restricted_policy_owner(school)<>actor)then raise exception 'Human policy owner approval required'using errcode='42501';end if;
   if command_name='followup'and(revision.follow_up_owner_id is distinct from actor or role_name<>'teacher')then raise exception 'Exact assigned manual followup owner required'using errcode='42501';end if;
  end if;
 end if;
 if command_name='create'and(jsonb_typeof(payload->'occurredAt')is distinct from'string'or jsonb_typeof(payload->'title')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200 or jsonb_typeof(payload->'note')is distinct from'string'or length(btrim(payload->>'note'))not between 1 and 4000 or payload->'confirmFactualRecord'is distinct from'true'::jsonb)then raise exception 'Explicit actual factual record required'using errcode='22023';end if;
 if command_name='approve'and(payload->'confirmApproval'is distinct from'true'::jsonb or jsonb_typeof(payload->'followUpOwnerId')is distinct from'string'or jsonb_typeof(payload->'instructions')is distinct from'string'or length(btrim(payload->>'instructions'))not between 1 and 4000)then raise exception 'Manual followup owner approval required'using errcode='22023';end if;
 if command_name='followup'and(payload->'confirmManualAction'is distinct from'true'::jsonb or jsonb_typeof(payload->'status')is distinct from'string'or payload->>'status'not in('IN_PROGRESS','COMPLETED')or jsonb_typeof(payload->'note')is distinct from'string'or length(btrim(payload->>'note'))not between 1 and 4000)then raise exception 'Actual manual followup confirmation required'using errcode='22023';end if;
 if command_name='create'and(payload-array['courseId','learnerId','occurredAt','title','note','confirmFactualRecord']<>'{}'::jsonb or(payload->>'occurredAt')::timestamptz>clock_timestamp())then raise exception 'Exact observed create fields required'using errcode='22023';end if;
 if command_name='correct'and(record.author_id<>actor or payload-array['expectedRevision','title','note','reason','confirmCorrection']<>'{}'::jsonb or payload->'confirmCorrection'is distinct from'true'::jsonb or jsonb_typeof(payload->'title')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200 or jsonb_typeof(payload->'note')is distinct from'string'or length(btrim(payload->>'note'))not between 1 and 4000)then raise exception 'Exact author correction fields required'using errcode='22023';end if;
 if command_name='approve'and(payload-array['expectedRevision','followUpOwnerId','instructions','reason','confirmApproval']<>'{}'::jsonb or not internal.restricted_course_teacher(school,record.course_id,(payload->>'followUpOwnerId')::uuid))then raise exception 'Exact approved current owner fields required'using errcode='22023';end if;
 if command_name='followup'and payload-array['expectedRevision','status','note','confirmManualAction']<>'{}'::jsonb then raise exception 'Exact manual followup fields required'using errcode='22023';end if;
 if command_name in('correct','approve','followup')and(jsonb_typeof(payload->'expectedRevision')is distinct from'number'or(payload->>'expectedRevision')!~'^[1-9][0-9]*$')then raise exception 'Exact source revision required'using errcode='22023';end if;
 if command_name in('correct','approve')and(jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000)then raise exception 'Human review reason required'using errcode='22023';end if;
 if command_name='create'then perform internal.lock_restricted_relation(course.id,(payload->>'learnerId')::uuid,case when role_name='teacher'then actor else null end);if not(role_name='admin'and internal.restricted_policy_owner(school)=actor or role_name='teacher'and internal.restricted_course_teacher(school,course.id,actor))then raise exception 'Current record actor relation changed'using errcode='42501';end if;
 elsif command_name<>'policy'then perform internal.lock_restricted_relation(record.course_id,record.learner_id,case when command_name='approve'then(payload->>'followUpOwnerId')::uuid else case when role_name='teacher'then actor else null end end);if not internal.restricted_record_allowed(record.id)then raise exception 'Current restricted object relation changed'using errcode='42501';end if;end if;
 if command_name='policy'then perform 1 from app.memberships member where member.school_id=school and member.actor_id=actor for share;end if;
 select p.*into policy from app.restricted_record_policies p where p.school_id=school order by p.version desc limit 1;
 role_name:="authorization".current_role(school);
 if not"authorization".can_access_school(school)or not"authorization".has_entitlement(school,'restricted.records')or not internal.restricted_synthetic_school(school)or role_name is null or role_name not in('admin','teacher')or(command_name in('policy','approve')and(role_name<>'admin'or(command_name='approve'and internal.restricted_policy_owner(school)<>actor)))or(command_name='followup'and(role_name<>'teacher'or revision.follow_up_owner_id is distinct from actor))then raise exception 'Current restricted action role required'using errcode='42501';end if;
 if command_name<>'policy'and not internal.restricted_policy_enabled(school)then raise exception 'Current restricted policy disabled'using errcode='42501';end if;
 reservation:=internal.begin_command(command_key,'restricted.record.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then if command_name='policy'then return internal.read_restricted_policy();else return internal.restricted_record_projection((reservation->'response'->>'id')::uuid);end if;elsif reservation->>'state'<>'NEW'then raise exception 'Restricted action pending'using errcode='22023';end if;
 if command_name='policy'then select coalesce(max(p.version),0)into latest from app.restricted_record_policies p where p.school_id=school;if latest::numeric is distinct from(payload->>'expectedVersion')::numeric then raise exception 'Restricted policy version changed'using errcode='22023';end if;insert into app.restricted_record_policies(school_id,version,enabled,purpose,source_basis,retention_status,retention_note,owner_id,reason,approved_by)values(school,latest+1,(payload->>'enabled')::boolean,'BASIC_INCIDENT_NOTE','SCHOOL_AUTHORED','SYNTHETIC_ONLY',payload->>'retentionNote',actor,payload->>'reason',actor)returning id into rid;receipt:=internal.read_restricted_policy();record_id:=rid;
 elsif command_name='create'then
  if payload-array['courseId','learnerId','occurredAt','title','note','confirmFactualRecord']<>'{}'::jsonb or payload->'confirmFactualRecord'is distinct from'true'::jsonb or jsonb_typeof(payload->'title')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200 or jsonb_typeof(payload->'note')is distinct from'string'or length(btrim(payload->>'note'))not between 1 and 4000 or jsonb_typeof(payload->'occurredAt')is distinct from'string'or(payload->>'occurredAt')::timestamptz>clock_timestamp()then raise exception 'Actual observed record context required'using errcode='22023';end if;
  insert into app.restricted_records(school_id,policy_id,course_id,learner_id,author_id,occurred_at)values(school,policy.id,course.id,(payload->>'learnerId')::uuid,actor,(payload->>'occurredAt')::timestamptz)returning id into record_id;insert into app.restricted_record_revisions(school_id,policy_id,record_id,revision,title,note,state,reason,actor_id)values(school,policy.id,record_id,1,payload->>'title',payload->>'note','AWAITING_REVIEW','Factual source submitted for human review.',actor)returning id into rid;receipt:=internal.restricted_record_projection(record_id);
 else
  if jsonb_typeof(payload->'expectedRevision')is distinct from'number'or(payload->>'expectedRevision')!~'^[1-9][0-9]*$'or revision.revision::numeric is distinct from(payload->>'expectedRevision')::numeric then raise exception 'Exact restricted revision changed'using errcode='22023';end if;
  if command_name='correct'then
   if record.author_id<>actor or payload-array['expectedRevision','title','note','reason','confirmCorrection']<>'{}'::jsonb or payload->'confirmCorrection'is distinct from'true'::jsonb or jsonb_typeof(payload->'title')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200 or jsonb_typeof(payload->'note')is distinct from'string'or length(btrim(payload->>'note'))not between 1 and 4000 or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'Author correction review required'using errcode='22023';end if;
   insert into app.restricted_record_revisions(school_id,policy_id,record_id,revision,title,note,state,reason,actor_id)values(school,policy.id,record.id,revision.revision+1,payload->>'title',payload->>'note','AWAITING_REVIEW',payload->>'reason',actor)returning id into rid;
  elsif command_name='approve'then
   if payload-array['expectedRevision','followUpOwnerId','instructions','reason','confirmApproval']<>'{}'::jsonb or payload->'confirmApproval'is distinct from'true'::jsonb or not internal.restricted_course_teacher(school,record.course_id,(payload->>'followUpOwnerId')::uuid)or jsonb_typeof(payload->'instructions')is distinct from'string'or length(btrim(payload->>'instructions'))not between 1 and 4000 or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'Explicit current followup owner review required'using errcode='22023';end if;
   insert into app.restricted_record_revisions(school_id,policy_id,record_id,revision,title,note,state,follow_up_owner_id,follow_up_instructions,reason,actor_id)values(school,policy.id,record.id,revision.revision+1,revision.title,revision.note,'APPROVED_FOLLOW_UP',(payload->>'followUpOwnerId')::uuid,payload->>'instructions',payload->>'reason',actor)returning id into rid;
  elsif command_name='followup'then
   if payload-array['expectedRevision','status','note','confirmManualAction']<>'{}'::jsonb or payload->'confirmManualAction'is distinct from'true'::jsonb or jsonb_typeof(payload->'status')is distinct from'string'or payload->>'status'not in('IN_PROGRESS','COMPLETED')or revision.state not in('APPROVED_FOLLOW_UP','IN_PROGRESS')or jsonb_typeof(payload->'note')is distinct from'string'or length(btrim(payload->>'note'))not between 1 and 4000 then raise exception 'Explicit manual followup action required'using errcode='22023';end if;
   insert into app.restricted_record_revisions(school_id,policy_id,record_id,revision,title,note,state,follow_up_owner_id,follow_up_instructions,follow_up_note,reason,actor_id)values(school,policy.id,record.id,revision.revision+1,revision.title,revision.note,payload->>'status',revision.follow_up_owner_id,revision.follow_up_instructions,payload->>'note','Assigned teacher records manual action.',actor)returning id into rid;
  else raise exception 'Restricted command invalid'using errcode='22023';end if;record_id:=record.id;receipt:=internal.restricted_record_projection(record.id);
 end if;
 event_version:=case when command_name='policy'then latest+1 else case when command_name='create'then 1 else revision.revision+1 end end;
 perform internal.append_audit('restricted.record.'||command_name,'restricted_record',rid,request_id,'succeeded',jsonb_build_object('recordId',record_id,'policyId',case when command_name='policy'then rid else policy.id end,'version',event_version));perform internal.enqueue_event('restricted.record.changed','restricted_record',rid,event_version,jsonb_build_object('kind',command_name,'policyId',case when command_name='policy'then rid else policy.id end),'restricted-record:'||rid::text);perform internal.finish_command(command_key,'restricted.record.'||command_name,fingerprint,jsonb_build_object('id',record_id));return receipt;
end$$;

create function internal.read_restricted_choices(target_course uuid,page_limit integer,page_cursor uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();items jsonb;begin
 if not internal.restricted_policy_enabled(school)or"authorization".current_role(school)is null or"authorization".current_role(school)not in('admin','teacher')or page_limit is null or page_limit not between 1 and 25 then raise exception 'Restricted purpose choices denied'using errcode='42501';end if;
 if target_course is null then
  select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'className',class.name)order by c.id),'[]'::jsonb)into items from(select c.*from app.courses c where c.school_id=school and(page_cursor is null or c.id>page_cursor)and("authorization".current_role(school)='admin'and internal.restricted_policy_owner(school)=actor or"authorization".current_role(school)='teacher'and internal.restricted_course_teacher(school,c.id,actor))order by c.id limit page_limit+1)c join app.classes class on class.school_id=c.school_id and class.id=c.class_id;
 else
  if not("authorization".current_role(school)='admin'and internal.restricted_policy_owner(school)=actor or internal.restricted_course_teacher(school,target_course,actor))then raise exception 'Exact restricted course denied'using errcode='42501';end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',p.actor_id,'displayName',p.display_name,'role',m.role)order by p.actor_id),'[]'::jsonb)into items from(select p.*from app.people p where p.school_id=school and(page_cursor is null or p.actor_id>page_cursor)and p.synthetic and("authorization".current_learner_course(school,target_course,p.actor_id)or internal.restricted_course_teacher(school,target_course,p.actor_id))order by p.actor_id limit page_limit+1)p join app.memberships m on m.school_id=p.school_id and m.actor_id=p.actor_id;
 end if;return jsonb_build_object('items',case when jsonb_array_length(items)>page_limit then items-page_limit else items end,'nextCursor',case when jsonb_array_length(items)>page_limit then items->(page_limit-1)->>'id'else null end);
end$$;
create function internal.read_restricted_history(target uuid,page_limit integer,page_cursor uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();items jsonb;begin
 if not internal.restricted_record_allowed(target)or page_limit is null or page_limit not between 1 and 25 then raise exception 'Restricted source history denied'using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'revision',r.revision,'title',r.title,'note',r.note,'state',r.state,'reason',r.reason,'createdAt',r.created_at)order by r.id),'[]'::jsonb)into items from(select r.*from app.restricted_record_revisions r where r.school_id=school and r.record_id=target and(page_cursor is null or r.id>page_cursor)order by r.id limit page_limit+1)r;
 if octet_length(items::text)>250000 then raise exception 'Restricted history requires smaller page'using errcode='22023';end if;return jsonb_build_object('items',case when jsonb_array_length(items)>page_limit then items-page_limit else items end,'nextCursor',case when jsonb_array_length(items)>page_limit then items->(page_limit-1)->>'id'else null end);
end$$;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.read_school_audit(jsonb)'::regprocedure);anchor:='audit.school_id=school and';if position(anchor in definition)=0 then raise exception 'Generic school audit source filter changed'using errcode='22023';end if;execute replace(definition,anchor,'audit.school_id=school and audit.entity_type<>''restricted_record'' and audit.action not like''restricted.record.%'' and');
end$$;
do $$declare tab text;begin foreach tab in array array['restricted_record_policies','restricted_records','restricted_record_revisions']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);execute format('revoke all on app.%I from public,anon,authenticated,service_role,cuevo_api,cuevo_worker',tab);execute format('create trigger immutable_history before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger immutable_truncate before truncate on app.%I for each statement execute function internal.academic_history_immutable()',tab);end loop;end$$;
