grant execute on function internal.read_restricted_policy(),internal.read_restricted_records(integer,uuid),internal.restricted_record_command(text,uuid,jsonb,text,text,text),internal.read_restricted_choices(uuid,integer,uuid),internal.read_restricted_history(uuid,integer,uuid)to cuevo_api;
do $$declare definition text;anchor text;begin definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'Restricted source event dispatcher changed'using errcode='22023';end if;definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''restricted.record.changed'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.entity_type<>''restricted_record''or not((e.metadata->>''kind''=''policy''and exists(select 1 from app.restricted_record_policies p where p.school_id=e.school_id and p.id=e.entity_id and p.approved_by=e.actor_id and p.version=e.version and e.metadata->>''policyId''=p.id::text))or(e.metadata->>''kind''in(''create'',''correct'',''approve'',''followup'')and exists(select 1 from app.restricted_record_revisions r join app.restricted_records record on record.school_id=r.school_id and record.id=r.record_id join app.restricted_record_policies p on p.school_id=r.school_id and p.id=r.policy_id where r.school_id=e.school_id and r.id=e.entity_id and r.actor_id=e.actor_id and r.revision=e.version and e.metadata->>''policyId''=p.id::text)))or not exists(select 1 from internal.audit_events audit where audit.school_id=e.school_id and audit.actor_id=e.actor_id and audit.entity_id=e.entity_id and audit.entity_type=''restricted_record''and audit.outcome=''succeeded''and(audit.metadata->>''version'')::integer=e.version and audit.metadata->''policyId''=e.metadata->''policyId''and audit.action=(''restricted.record.''||(e.metadata->>''kind'')))then raise exception ''Restricted event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Restricted source lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;end$$;
